Функция ПолучитьСальдоСчета(Счет) Экспорт

	Если Счет = Неопределено Тогда
		Возврат 0;
	КонецЕсли;

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	СУММА(Обороты.Дебет) КАК Дебет,
	|	СУММА(Обороты.Кредит) КАК Кредит
	|ИЗ
	|	(ВЫБРАТЬ
	|		Хозрасчетный.Сумма КАК Дебет,
	|		0 КАК Кредит
	|	ИЗ
	|		РегистрБухгалтерии.Хозрасчетный КАК Хозрасчетный
	|	ГДЕ
	|		Хозрасчетный.Активность
	|		И Хозрасчетный.СчетДт В ИЕРАРХИИ(&Счет)
	|	
	|	ОБЪЕДИНИТЬ ВСЕ
	|	
	|	ВЫБРАТЬ
	|		0,
	|		Хозрасчетный.Сумма
	|	ИЗ
	|		РегистрБухгалтерии.Хозрасчетный КАК Хозрасчетный
	|	ГДЕ
	|		Хозрасчетный.Активность
	|		И Хозрасчетный.СчетКт В ИЕРАРХИИ(&Счет)) КАК Обороты";

	Запрос.УстановитьПараметр("Счет", Счет);

	Выборка = Запрос.Выполнить().Выбрать();

	Дебет = 0;
	Кредит = 0;

	Если Выборка.Следующий() Тогда
		Если Выборка.Дебет <> Null Тогда
			Дебет = Выборка.Дебет;
		КонецЕсли;
		Если Выборка.Кредит <> Null Тогда
			Кредит = Выборка.Кредит;
		КонецЕсли;
	КонецЕсли;

	Если Счет.Вид = ВидСчета.Пассивный Тогда
		Возврат Кредит - Дебет;
	Иначе
		Возврат Дебет - Кредит;
	КонецЕсли;

КонецФункции
